/*
 * prog38_continued_fraction
 *
 * Re‑implementation of the original binary (after de‑obfuscation).
 * The program expects two integer arguments and prints the continued
 * fraction representation of the first argument divided by the second.
 *
 * Output format:
 *   [q0; q1, q2, ...]
 *   – the first quotient is printed after '['.
 *   – if there is more than one quotient a '; ' separates the first
 *     from the rest, and subsequent quotients are separated by ', '.
 *   – an empty list "[]" is printed when the divisor is zero.
 *
 * Error messages (exact strings, matching the original binary):
 *   NO_INPUT      – fewer than two arguments are supplied.
 *   BAD_INPUT     – either argument is not a valid integer.
 *   OUT_OF_RANGE  – |second argument| > 100000.
 *
 * The implementation follows the logic observed in the de‑compiled
 * state‑machine of the original program, but expressed in clear C.
 */

#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <inttypes.h>

int main(int argc, char **argv)
{
    /* -----------------------------------------------------------------
     * Argument handling
     * ----------------------------------------------------------------- */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    char *end1, *end2;
    long a = strtol(argv[1], &end1, 10);
    long b = strtol(argv[2], &end2, 10);

    /* Both arguments must be completely consumed by strtol */
    if (*end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* Range check – the original program limits the absolute value of
       the second argument (the divisor) to 100 000. */
    if (llabs((long long)b) > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* -----------------------------------------------------------------
     * Continued‑fraction computation (Euclidean algorithm)
     * ----------------------------------------------------------------- */
    long quotients[201];          /* more than enough for 64‑bit inputs */
    int  qcount = 0;

    long dividend = a;
    long divisor  = b;

    /* The original program treats a zero divisor as an empty list. */
    if (divisor == 0) {
        puts("[]");
        return 0;
    }

    /* Use the absolute value of the divisor – the original code makes
       the divisor positive before the Euclidean loop. */
    if (divisor < 0)
        divisor = -divisor;

    while (divisor != 0) {
        long q = dividend / divisor;          /* integer quotient */
        quotients[qcount++] = q;

        long r = dividend - q * divisor;      /* remainder */
        dividend = divisor;
        divisor  = r;
    }

    /* -----------------------------------------------------------------
     * Output formatting
     * ----------------------------------------------------------------- */
    putchar('[');
    if (qcount > 0) {
        /* first quotient */
        printf("%ld", quotients[0]);

        if (qcount > 1) {
            /* separator between integer part and fractional part */
            printf("; ");
        }

        /* remaining quotients */
        for (int i = 1; i < qcount; ++i) {
            printf("%ld", quotients[i]);
            if (i + 1 < qcount) {
                printf(", ");
            }
        }
    }
    putchar(']');
    putchar('\n');          /* matches the original `puts("]")` */

    return 0;
}
